{
  "rationale": "Build the office from its architectural shell outward, then add furniture, recognizable details, and a final appearance pass.",
  "stages": [
    {
      "stage_id": 1,
      "title": "Room and viewpoint",
      "targets": [
        "room shell",
        "window and door opening",
        "camera",
        "basic lighting"
      ],
      "completed_scope": "The room has its floor, walls, ceiling and beam, left glazed opening, approximate camera framing, and broad illumination."
    },
    {
      "stage_id": 2,
      "title": "Office furniture",
      "targets": [
        "desk",
        "visitor chairs",
        "office chair",
        "right wall cabinetry"
      ],
      "completed_scope": "The main white desk, two green visitor chairs, rear office chair, and wood wall cabinetry are present in their reference positions."
    },
    {
      "stage_id": 3,
      "title": "Plants and fixtures",
      "targets": [
        "potted plants",
        "radiator",
        "ceiling light",
        "wall art"
      ],
      "completed_scope": "Both plants, the rear radiator, ceiling light panel, and framed artwork establish the room’s secondary silhouettes."
    },
    {
      "stage_id": 4,
      "title": "Desktop details",
      "targets": [
        "computer",
        "desk accessories",
        "small decor",
        "architectural trim"
      ],
      "completed_scope": "The monitor and desktop accessories are in place, along with visible window hardware, baseboards, and other small architectural details."
    },
    {
      "stage_id": 5,
      "title": "Appearance and global check",
      "targets": [
        "materials",
        "lighting balance",
        "composition",
        "object relationships"
      ],
      "completed_scope": "Materials and lighting reflect the reference, and the overall framing, proportions, spacing, and visible object relationships have been checked."
    }
  ]
}

