    "code": "from sceneact import *\n\nscene = Scene('Office furniture additions')\nwhite = (0.88, 0.88, 0.86)\nwhite_edge = (0.96, 0.96, 0.94)\ngreen = (0.43, 0.47, 0.045)\ngreen_side = (0.34, 0.39, 0.035)\nmetal = (0.30, 0.32, 0.31)\ndark = (0.12, 0.13, 0.12)\nwood = (0.56, 0.36, 0.21)\nwood_edge = (0.39, 0.25, 0.15)\n\n# The broad desk faces the camera, with a solid modesty panel and slab ends.\ndesk = Asset('White office desk')\ndesk.include('desktop', box((2.75, 1.02, 0.09), center=(0.90, 2.05, 0.82), color=white_edge))\ndesk.include('front modesty panel', box((2.56, 0.075, 0.68), center=(0.90, 1.64, 0.43), color=white))\ndesk.include('left end panel', box((0.10, 0.89, 0.72), center=(-0.39, 2.05, 0.40), color=white))\ndesk.include('right end panel', box((0.10, 0.89, 0.72), center=(2.19, 2.05, 0.40), color=white))\ndesk.include('recessed plinth', box((2.46, 0.64, 0.07), center=(0.90, 2.06, 0.045), color=(0.62, 0.62, 0.59)))\nscene.include('desk', desk)\n\n# Two upholstered swivel visitor chairs, with their backs toward the camera.\ndef visitor_chair(name, x, y):\n    chair = Asset(name)\n    chair.include('upholstered back', fillet_box((0.92, 0.18, 0.94), radius=0.09, center=(x, y-0.30, 0.91), color=green))\n    chair.include('seat cushion', fillet_box((0.86, 0.70, 0.16), radius=0.08, center=(x, y+0.01, 0.48), color=green))\n    for side in (-1, 1):\n        arm = fillet_box((0.12, 0.63, 0.33), radius=0.055, center=(x+side*0.47, y-0.02, 0.64), color=green_side)\n        arm.turn('y', side * -10)\n        chair.include('arm left' if side < 0 else 'arm right', arm)\n    chair.include('central stem', rod(0.045, start=(x,y,0.12), end=(x,y,0.46), color=metal))\n    chair.include('base left right', box((0.98, 0.055, 0.045), center=(x,y,0.055), color=metal))\n    chair.include('base front back', box((0.055, 0.86, 0.045), center=(x,y,0.055), color=metal))\n    return chair\nscene.include('visitor chair left', visitor_chair('Left visitor chair', 0.20, 0.38))\nscene.include('visitor chair right', visitor_chair('Right visitor chair', 1.90, 0.35))\n\n# Taller, subdued upholstered chair behind the desk.\noffice = Asset('Rear office chair')\noffice.include('high back', fillet_box((0.70, 0.20, 0.98), radius=0.10, center=(0.56, 2.75, 1.16), color=(0.35,0.34,0.31)))\noffice.include('seat', fillet_box((0.70, 0.62, 0.14), radius=0.07, center=(0.56, 2.62, 0.65), color=(0.30,0.29,0.27)))\noffice.include('stem', rod(0.04, start=(0.56,2.68,0.12), end=(0.56,2.68,0.62), color=dark))\nfor dx,dy in ((0.37,0),(-0.37,0),(0,0.33),(0,-0.33)):\n    office.include('base spoke %s %s' % (dx,dy), rod(0.025, start=(0.56,2.68,0.10), end=(0.56+dx,2.68+dy,0.05), color=dark))\nscene.include('office chair', office)\n\n# Long low wood cabinetry runs along the right wall; individual fronts retain seams.\ncabinet = Asset('Right wall wood cabinetry')\ncabinet.include('cabinet body', box((0.48, 4.65, 1.07), center=(2.88, 1.55, 0.64), color=wood_edge))\ncabinet.include('top cap', box((0.52, 4.72, 0.045), center=(2.85, 1.55, 1.19), color=wood))\ncabinet.include('toe kick', box((0.38, 4.62, 0.12), center=(2.94, 1.55, 0.06), color=(0.23,0.22,0.20)))\nfor j in range(4):\n    yy = -0.18 + j*1.16\n    for row in range(2):\n        zz = 0.40 + row*0.50\n        cabinet.include('wood front %d %d' % (j,row), box((0.035, 1.145, 0.485), center=(2.625, yy, zz), color=wood if (j+row)%2 == 0 else (0.59,0.39,0.23)))\nscene.include('wall cabinetry', cabinet)\n\nrealize(scene, clear=False)",
